SELECT d.document_id AS document_id, d.document_no AS document_no, d.document_date AS document_date, d.document_type_code AS document_type, d.document_status_code AS status, d.vat_mode AS vat_mode, d.currency_code AS currency_code, d.language_code AS language_code, d.payment_term_code AS payment_term_code, d.payment_terms_text AS payment_terms_text, d.customer_address_id AS customer_address_id, d.delivery_address_id AS delivery_address_id, d.customer_name AS customer_name, IIf(Nz(a.company_name,'')<>'',a.company_name,Nz(d.customer_name,'')) AS customer_display_name, Nz(a.street,'') AS customer_street, Nz(a.zip_code,'') AS customer_postal_code, Nz(a.city,'') AS customer_city, Nz(a.country_code,'') AS customer_country, IIf(Nz(a.company_name,'')<>'',a.company_name,Nz(d.customer_name,'')) AS billing_display_name, Nz(a.street,'') AS billing_street, Nz(a.zip_code,'') AS billing_zip_code, Nz(a.city,'') AS billing_city, Nz(a.country_code,'') AS billing_country_code, IIf(Nz(da.company_name,'')<>'',da.company_name,'') AS delivery_display_name, Nz(da.street,'') AS delivery_street, Nz(da.zip_code,'') AS delivery_zip_code, Nz(da.city,'') AS delivery_city, Nz(da.country_code,'') AS delivery_country_code, IIf(Not IsNull(d.delivery_address_id) And d.delivery_address_id<>d.customer_address_id,True,False) AS has_delivery_address, CCur(Nz(d.subtotal_net_amount,0)) AS subtotal_net_amount, CCur(Nz(d.header_discount_amount,0)) AS header_discount_amount, CCur(Nz(d.header_surcharge_amount,0)) AS header_surcharge_amount, CCur(Nz(d.total_net,0)) AS net_amount, CCur(Nz(d.total_vat,0)) AS vat_amount, CCur(Nz(d.total_gross,0)) AS gross_amount, p.document_position_id AS document_position_id, CLng(Nz(p.line_no,0)) AS line_no, '' AS item_no, Nz(p.description,'') AS description, CDbl(Nz(p.quantity,0)) AS quantity, Nz(p.unit_code,'') AS unit_code, CCur(Nz(p.unit_price,0)) AS unit_price, CDbl(Nz(p.vat_rate,0)) AS position_vat_rate, Nz(p.discount_type,'NONE') AS discount_type, CCur(Nz(p.discount_value,0)) AS discount_value, CCur(Nz(p.line_discount_amount,0)) AS line_discount_amount, Nz(p.surcharge_type,'NONE') AS surcharge_type, CCur(Nz(p.surcharge_value,0)) AS surcharge_value, CCur(Nz(p.line_surcharge_amount,0)) AS line_surcharge_amount, CCur(Nz(p.line_base_amount,0)) AS line_base_amount, CCur(Nz(p.line_total_net,0)) AS line_net_amount, CCur(Nz(p.line_total_vat,0)) AS line_vat_amount, CCur(Nz(p.line_total_gross,0)) AS line_gross_amount
FROM ((doc_document AS d LEFT JOIN adr_address AS a ON d.customer_address_id = a.address_id) LEFT JOIN adr_address AS da ON d.delivery_address_id = da.address_id) LEFT JOIN doc_document_position AS p ON d.document_id = p.document_id
ORDER BY d.document_id, p.line_no, p.document_position_id;
